const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
const HALF_REIMBURSEMENT_SHARE = 0.5;

const isDeeplyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;

// Deeply enchanted items are reimbursed at half the damage: the MHPCO holds
// that their magic bears part of its own misfortune.
const reimbursementFor = (item: Item, damage: Damage): number =>
  isDeeplyEnchanted(item)
    ? damage.amount * HALF_REIMBURSEMENT_SHARE
    : damage.amount;
